      - name: Start moto in the background
        run: |
          nohup moto_server -p 5555 > moto.log 2>&1 &
          for i in $(seq 1 30); do
            if (echo > /dev/tcp/127.0.0.1/5555) 2>/dev/null; then exit 0; fi
            sleep 1
          done
          cat moto.log
          exit 1

      - name: Install
        run: npm ci

      - name: Typecheck
        working-directory: conversation
        run: npm run typecheck

      - name: Test
        working-directory: conversation
        env:
          CHATTICUS_TEST_AWS_ENDPOINT: http://127.0.0.1:5555
        run: npm test
